"""Regenerate MinHash vectors with an independent, direct Python reference.

Run from the hash module: python3 testdata/minhash_vectors.py
"""

import hashlib
import json
import pathlib

MODULUS = 2147483647
BASE = 1000003
PROBE = 2654435761
STRIDE = 55
K = 128
SHINGLE = 5


def tokens(text):
    result = []
    current = bytearray()
    for byte in text.encode("utf-8"):
        word = byte >= 128 or byte == 95 or 48 <= byte <= 57 or 65 <= byte <= 90 or 97 <= byte <= 122
        if word:
            current.append(byte + 32 if 65 <= byte <= 90 else byte)
        elif current:
            result.append(bytes(current))
            current.clear()
    if current:
        result.append(bytes(current))
    return result


def signature(pieces, domain):
    words = tokens("".join(p["text"] * p["times"] for p in pieces))
    normalized = hashlib.sha256(b" ".join(words)).hexdigest()
    if not words:
        return {"tokens": 0, "normalized": normalized}
    hashes = []
    for word in words:
        value = 0x811C9DC5
        for byte in word:
            value = ((value * 0x01000193) & 0xFFFFFFFF) ^ byte
        hashes.append(value % MODULUS)
    width = min(SHINGLE, len(hashes))
    bins = [None] * K
    for offset in range(len(hashes) - width + 1):
        value = 0
        for token in hashes[offset:offset + width]:
            value = (value * BASE + token) % MODULUS
        slot = value % K
        if bins[slot] is None or value < bins[slot]:
            bins[slot] = value
    sketch = []
    for index, value in enumerate(bins):
        if value is None:
            start = ((index + 1) * PROBE) % MODULUS
            value = next(bins[(start + STRIDE * a) % K]
                         for a in range(1, K + 1)
                         if bins[(start + STRIDE * a) % K] is not None)
        sketch.append(value)

    def frame(fields):
        return b"".join(str(len(field)).encode() + b":" + field for field in fields)

    bands = []
    for band in range(16):
        data = b"".join(value.to_bytes(4, "big") for value in sketch[8 * band:8 * (band + 1)])
        digest = hashlib.sha256(frame([domain.encode(), str(band).encode(), data])).digest()
        bands.append(digest[:8].hex())
    return {"tokens": len(words), "normalized": normalized, "sketch": sketch, "bands": bands}


path = pathlib.Path(__file__).with_name("minhash_vectors.json")
vectors = json.loads(path.read_text())
vectors["source"] = "Generated by minhash_vectors.py, the independent direct Python reference in this directory."
for case in vectors["cases"]:
    case.update(signature(case["pieces"], vectors["domain"]))
near = vectors["near"]
a = signature(near["a"], vectors["domain"])["sketch"]
b = signature(near["b"], vectors["domain"])["sketch"]
near["equal_bins"] = sum(x == y for x, y in zip(a, b))
path.write_text(json.dumps(vectors, indent=1, ensure_ascii=False) + "\n")
